using System;
using System.IO;
using System.Linq;
using System.Text;

namespace Fuxion.Tools.Core.Layout;

/// <summary>
/// The header of what fx generates (plan P, decision 6), in the comment of each format:
/// <code>
/// ===      GENERATED by Fuxion.Tools (fx) - DO NOT EDIT      ===
/// Generated from: &lt;where it comes from&gt;
/// Regenerated with: &lt;the command&gt;
/// </code>
/// fx never overwrites a file without <see cref="Mark"/>. What admits no comments (an image, a JSON) is fx's because
/// <c>_fx/.inherited/inherited.yaml</c> lists it.
/// </summary>
public static class FxHeader
{
	public const string Mark = "GENERATED by Fuxion.Tools (fx)";
	public const string Title = "===      GENERATED by Fuxion.Tools (fx) - DO NOT EDIT      ===";

	/// <summary>The command that regenerates everything fx writes.</summary>
	public const string Sync = "fx sync";

	public static bool IsGenerated(string text) => text.Contains(Mark, StringComparison.Ordinal);

	static string[] Lines(string from, string regenerated) => [Title, $"Generated from: {from}", $"Regenerated with: {regenerated}"];

	/// <summary>The header as <c>#</c> comments (YAML, <c>.gitignore</c>), each line with '\n'.</summary>
	public static string Hash(string from, string regenerated = Sync) => string.Concat(Lines(from, regenerated).Select(l => $"# {l}\n"));

	/// <summary>The header as XML comments (MSBuild, <c>.slnx</c>), each line with '\n' and <paramref name="indent"/> before it.</summary>
	public static string Xml(string from, string regenerated = Sync, string indent = "")
		=> string.Concat(Lines(from, regenerated).Select(l => $"{indent}<!-- {l} -->\n"));

	/// <summary>
	/// <paramref name="content"/> without the header fx put on it (a file copied again from <c>_fx/.inherited/</c>
	/// to the level below gets a new one).
	/// </summary>
	public static byte[] Strip(byte[] content)
	{
		var text = new UTF8Encoding(false).GetString(content);
		if (!IsGenerated(text))
			return content;
		var lines = text.Replace("\r\n", "\n").Split('\n').ToList();
		var at = lines.Count > 0 && lines[0].StartsWith("<?xml", StringComparison.Ordinal) ? 1 : 0;
		if (lines.Count >= at + 3 && lines[at].Contains(Title, StringComparison.Ordinal))
			lines.RemoveRange(at, 3);
		return new UTF8Encoding(false).GetBytes(string.Join('\n', lines));
	}

	/// <summary>
	/// <paramref name="content"/> (UTF-8 text, or anything else) with the header, if its format admits one: YAML gets
	/// <c>#</c> comments, MSBuild and XML files XML comments (after the XML declaration, if any). Anything else is returned
	/// as it is.
	/// </summary>
	public static byte[] Add(string path, byte[] content, string from, string regenerated = Sync)
	{
		var extension = Path.GetExtension(path).ToLowerInvariant();
		var hash = extension is ".yaml" or ".yml";
		var xml = extension is ".props" or ".targets" or ".xml" or ".slnx" or ".csproj" or ".fsproj" or ".vbproj" or ".proj";
		if (!hash && !xml)
			return content;
		var text = new UTF8Encoding(false).GetString(content).Replace("\r\n", "\n");
		if (hash)
			text = Hash(from, regenerated) + text;
		else if (text.StartsWith("<?xml", StringComparison.Ordinal) && text.IndexOf('\n') is var end and > 0)
			text = text[..(end + 1)] + Xml(from, regenerated) + text[(end + 1)..];
		else
			text = Xml(from, regenerated) + text;
		return new UTF8Encoding(false).GetBytes(text);
	}
}
